insert into public.community_editorial(slug,title,body,category,post_kind,position) values
('permanent-bookmarks','What website has earned a permanent place in your bookmarks?','A welcome prompt from Cowboy. Tell us the website, the task it solves, and what you actually use it for. Link its official address and mention any account or payment requirement you encountered. Let’s build something useful together.','discoveries','discussion',1),
('find-me-a-tool','What are you trying to get done? Let’s find a tool.','A help desk prompt from Cowboy. Describe your goal, device and browser, what you have tried, and whether you need a free option or no account. Start your own Find Me a Tool request for a question you can mark solved.','help','discussion',2),
('changed-links','A link changed, an export became paid, or a signup appeared?','A collection check-in from Cowboy. Use Report a change on a website card for a private owner report. For a public tip, tell us which tool changed and when you checked it. Keep passwords and personal information out of posts.','feedback','discussion',3),
('made-something','Show one thing you made with a tool from this collection.','A creative prompt from Cowboy. Share your goal, tools, steps and result. Tell us one detail that helped and one thing you would change. Use your own work or credit sources.','creative','discussion',4),
('manual-hunt','The lost manual hunt: what make and model do you need?','A Workbench prompt from Cowboy. Share the make, model and the instructions you need. Link a useful manual if you find one, and follow the manufacturer’s guidance for the job.','repair','discussion',5),
('photo-size','Photo too large to upload? What size do you need?','A practical prompt from Cowboy. Tell us the current file type and size, the target size, and your device. Share the tool and settings that worked without posting sensitive documents.','help','discussion',6),
('next-find','Which new find deserves the next closer look—and why?','A discovery prompt from Cowboy. Name a tool, give its official website, and explain a concrete task. Share whether you have tried it yourself and any limit you encountered.','discoveries','discussion',7),
('three-tool-workflow','One goal, three tools: share a useful workflow.','A maker prompt from Cowboy. Describe one goal and the steps between tools. Include the formats you moved between them and one tip that makes the process easier.','creative','discussion',8),
('small-fix','What small fix saved an item from being thrown away?','A Workbench prompt from Cowboy. Tell us the item, the symptom, the useful source and the outcome. Distinguish your experience from instructions that apply to a different model.','repair','discussion',9),
('phone-to-computer','Phone to computer: what file-transfer method works for you?','A practical prompt from Cowboy. Share your devices, the method you tried, and whether it needed an account or installation. Do not publish private pairing codes or files.','help','discussion',10),
('room-plan','Challenge: draw a room or project plan in your browser.','Cowboy’s challenge: make a simple room or project plan with a tool from the collection. Share the tool, your approach and what you learned. A rough useful sketch is welcome. Avoid sharing a private home address or access details.','creative','challenge',11),
('no-account','Share a useful no-account workflow you actually tried.','A discovery prompt from Cowboy. Tell us the task and the steps through export or download. Mention the date checked and any watermark, size, payment or account boundary you encountered.','discoveries','discussion',12),
('fewer-clicks','What part of the toolbox still takes too many clicks?','A feedback prompt from Cowboy. Describe the page, what you expected, and where you got stuck. Device and browser details help. Use the private report option for account concerns.','feedback','discussion',13),
('what-worked','What worked this fortnight? Share the thread that helped.','A community roundup prompt from Cowboy. Link a useful conversation and explain what you managed to do. Credit the person who helped and leave a tip for the next visitor.','discoveries','discussion',14)
